content.css:
html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent;
}
.snow-empty-state {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border-radius: var(--snow-radius, 18px);
  background: var(--snow-card-bg, #FFFFFF);
  color: var(--snow-ink-secondary, #6B7280);
  font-size: 12px;
  text-align: center;
  padding: 16px;
  border: 1px dashed rgba(0, 0, 0, 0.1);
}
.snow-empty-state .snow-empty-title {
  font-weight: 600;
  color: var(--snow-ink, #111827);
  font-size: 13px;
}
.snow-pillbar-host {
  --snow-primary: #007AFF;
  --snow-secondary: #AF52DE;
  --snow-tertiary: #00C7BE;
  --snow-positive: #34C759;
  --snow-warning: #FF9500;
  --snow-negative: #FF3B30;
  --snow-dark: #1C1C1E;
  --snow-ink: #111827;
  --snow-ink-secondary: #6B7280;
  --snow-ink-muted: #9CA3AF;
  --snow-on-dark: #FFFFFF;
  --snow-card-bg: #FFFFFF;
  --snow-border: #E5E7EB;
  --snow-radius: 18px;
  --snow-hover-bg: rgba(0, 122, 255, 0.055);
  --snow-hover-border: rgba(0, 122, 255, 0.14);
  --snow-selected-bg: rgba(0, 122, 255, 0.09);
  --snow-selected-border: rgba(0, 122, 255, 0.35);
  font-family: "Segoe UI", -apple-system, BlinkMacSystemFont, "SF Pro Display", "Inter", Roboto, Helvetica, Arial, sans-serif;
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  user-select: none;
  -webkit-font-smoothing: antialiased;
  color: var(--snow-ink, #111827);
  padding: 0;
  margin: 0;
  background: transparent;
  overflow: hidden;
}
.snow-pillbar-host *,
.snow-pillbar-host *::before,
.snow-pillbar-host *::after {
  box-sizing: border-box;
}
.snow-pillbar-card {
  width: 100%;
  height: 100%;
  background: var(--snow-card-bg, #FFFFFF);
  border-radius: var(--snow-radius, 18px);
  padding: 18px 20px 14px 20px;
  display: flex;
  flex-direction: column;
  position: relative;
}
.snow-pillbar-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 10px;
  flex-shrink: 0;
}
.snow-pillbar-header-left {
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
  flex-wrap: wrap;
}
.snow-pillbar-title {
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--snow-ink, #111827);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.snow-pillbar-legend {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}
.snow-legend-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 7px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 500;
  color: var(--snow-ink-secondary, #6B7280);
  cursor: pointer;
  border: none;
  background: transparent;
  font-family: "Segoe UI", -apple-system, BlinkMacSystemFont, "SF Pro Display", "Inter", Roboto, Helvetica, Arial, sans-serif;
  transition: opacity 220ms cubic-bezier(0.22, 1, 0.36, 1), background-color 220ms cubic-bezier(0.22, 1, 0.36, 1);
}
.snow-legend-item:hover {
  background: rgba(0, 0, 0, 0.045);
}
.snow-legend-item.is-dimmed {
  opacity: 0.35;
  text-decoration: line-through;
}
.snow-legend-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}
.snow-pillbar-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 3px 9px;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.045);
  color: var(--snow-ink-secondary, #6B7280);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
  flex-shrink: 0;
}
.snow-pillbar-body {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  width: 100%;
}
.snow-pillbar-svg {
  width: 100%;
  height: 100%;
  display: block;
  overflow: visible;
}
.snow-bar-capsule {
  pointer-events: none;
  transition: fill 220ms cubic-bezier(0.22, 1, 0.36, 1), opacity 220ms cubic-bezier(0.22, 1, 0.36, 1), filter 220ms cubic-bezier(0.22, 1, 0.36, 1);
}
.snow-bar-hit {
  cursor: pointer;
}
.snow-bar-micro {
  cursor: pointer;
  transition: opacity 200ms cubic-bezier(0.22, 1, 0.36, 1);
}
.snow-bar-micro:hover {
  opacity: 0.85;
}
.snow-pillbar-callout {
  position: absolute;
  pointer-events: none;
  background: var(--snow-dark, #1C1C1E);
  color: var(--snow-on-dark, #FFFFFF);
  font-size: 11.5px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  padding: 4px 10px;
  border-radius: 9px;
  white-space: nowrap;
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.16);
  transform: translate(-50%, -100%);
  opacity: 0;
  transition: opacity 180ms cubic-bezier(0.22, 1, 0.36, 1), left 200ms cubic-bezier(0.22, 1, 0.36, 1), top 200ms cubic-bezier(0.22, 1, 0.36, 1);
}
.snow-pillbar-callout.is-visible {
  opacity: 1;
}
